import java.util.*;

public class Main {
    static class Edge {
        int y, cap, flow, cost;
        Edge() {}
        Edge(int y, int cap, int flow, int cost) {
            this.y = y;
            this.cap = cap;
            this.flow = flow;
            this.cost = cost;
        }
    }

    static List<Edge> edges = new ArrayList<>();
    static final int MAXN = 14043;
    static List<Integer>[] adj = new ArrayList[MAXN];

    static long total_flow_cost = 0;
    static long[] dist = new long[MAXN];
    static int[] parent_node = new int[MAXN];
    static int[] parent_edge_idx = new int[MAXN];
    static int[] in_queue = new int[MAXN];

    static final long INF = (long)1e18;
    static int s = MAXN - 2;
    static int t = MAXN - 1;

    static int residual(int idx) {
        return edges.get(idx).cap - edges.get(idx).flow;
    }

    static void find_augmenting_path() {
        for (int i = 0; i < MAXN; i++) {
            dist[i] = INF;
            parent_node[i] = -1;
            parent_edge_idx[i] = -1;
            in_queue[i] = 0;
        }
        dist[s] = 0;
        Queue<Integer> q = new LinkedList<>();
        q.offer(s);
        in_queue[s] = 1;
        while (!q.isEmpty()) {
            int u = q.poll();
            in_queue[u] = 0;
            for (int e_idx : adj[u]) {
                if (residual(e_idx) == 0) continue;
                Edge e = edges.get(e_idx);
                int y = e.y;
                int cst = e.cost;
                if (dist[y] > dist[u] + cst) {
                    dist[y] = dist[u] + cst;
                    parent_node[y] = u;
                    parent_edge_idx[y] = e_idx;
                    if (in_queue[y] == 0) {
                        in_queue[y] = 1;
                        q.offer(y);
                    }
                }
            }
        }
        int cur = t;
        while (cur != s) {
            int e_idx = parent_edge_idx[cur];
            edges.get(e_idx).flow++;
            edges.get(e_idx ^ 1).flow--;
            cur = parent_node[cur];
        }
        total_flow_cost += dist[t];
    }

    static void create_edge(int from, int to, int capacity, int cost) {
        if (adj[from] == null) {
            adj[from] = new ArrayList<>();
        }
        adj[from].add(edges.size());
        edges.add(new Edge(to, capacity, 0, cost));
        if (adj[to] == null) {
            adj[to] = new ArrayList<>();
        }
        adj[to].add(edges.size());
        edges.add(new Edge(from, 0, 0, -cost));
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int k = sc.nextInt();
        int c = sc.nextInt();
        int d = sc.nextInt();

        for (int i = 0; i < MAXN; i++) {
            adj[i] = new ArrayList<>();
        }

        for (int i = 0; i < k; i++) {
            int x = sc.nextInt() - 1;
            create_edge(s, x, 1, 0);
        }

        int T = 101;
        for (int i = 0; i < T; i++) {
            create_edge(i * n, t, k, i * c);
        }

        for (int i = 0; i < m; i++) {
            int x = sc.nextInt() - 1;
            int y = sc.nextInt() - 1;
            for (int j = 0; j < T - 1; j++) {
                create_edge(x + j * n, y + j * n + n, 1, d * (j * 2 + 1));
            }
            for (int j = 0; j < T - 1; j++) {
                create_edge(y + j * n, x + j * n + n, 1, d * (j * 2 + 1));
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < T - 1; j++) {
                create_edge(i + j * n, i + j * n + n, k, 0);
            }
        }

        for (int i = 0; i < k; i++) {
            find_augmenting_path();
        }

        System.out.println(total_flow_cost);
        sc.close();
    }
}
